// MT2009_PLUS_ITEM_ACCOUNT_BOUND_V1 (antiflag): an account-bound item (the bots' G0 package, playerbot_yohara_g0.cpp) is never dropped,
// given, traded, sold to a merchant or put in a shop - the proto's flags and the instance's
DWORD		GetAntiFlag()		{ return (m_pProto ? m_pProto->dwAntiFlags : 0) | (m_bAccountBound ? (DWORD) (ITEM_ANTIFLAG_DROP |
			ITEM_ANTIFLAG_GIVE | ITEM_ANTIFLAG_SELL | ITEM_ANTIFLAG_MYSHOP | ITEM_ANTIFLAG_PKDROP) : 0); }

		void		SetYExtra(DWORD dw)	{ m_dwYExtra = dw; }
		// MT2009_PLUS_ITEM_ACCOUNT_BOUND_V1 (item member): bound to its owner's account - see GetAntiFlag; the overlay keeps the row
#define MT2009_PLUS_ITEM_ACCOUNT_BOUND_V1
		bool		IsAccountBound() const	{ return m_bAccountBound; }
		void		SetAccountBound(bool b)	{ m_bAccountBound = b; }

(void) Mt2009JadeBraceletRefine; // MT2009_PLUS_JADE_BRACELET_V1 (refine): replaced by V2
if (IsAccountBound()) // MT2009_PLUS_ITEM_ACCOUNT_BOUND_V1 (refine): the new item is bound too (its row follows it)
{
	pItem->SetAccountBound(true);
	Mt2009AccountBoundCarry(this, pItem);
}

item_table = pkItem->GetProto();
if (pkItem->IsAccountBound()) // MT2009_PLUS_ITEM_ACCOUNT_BOUND_V1 (stall): never on an old-style stall
{
	sys_err("MyShop: an account-bound item on pos (%d, %d) left out (name: %s)", pTable->pos.window_type, pTable->pos.cell, m_pkPC->GetName());
	++pTable;
	continue;
}
